					'import * as React from "react";\nimport { Bubble, BubbleContent } from "@workspace/ui/components/bubble";\nimport { Message, MessageContent } from "@workspace/ui/components/message";\n\n/*\n * align="end" is the whole mechanism for an outgoing turn: Message writes it\n * out as data-align and reverses its own flex row, so no ms-auto is needed.\n */\nexport function Message1Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="mx-auto flex w-full max-w-sm flex-col gap-6">\n\t\t\t<Message>\n\t\t\t\t<MessageContent>\n\t\t\t\t\t<Bubble variant="muted">\n\t\t\t\t\t\t<BubbleContent>Staging is green on 4.2. Want me to promote it?</BubbleContent>\n\t\t\t\t\t</Bubble>\n\t\t\t\t</MessageContent>\n\t\t\t</Message>\n\n\t\t\t{/*\n        Side alone is the first cue lost when a thread is read aloud or\n        collapsed into one column, so the bubble variant carries it too.\n      */}\n\t\t\t<Message align="end">\n\t\t\t\t<MessageContent>\n\t\t\t\t\t<Bubble>\n\t\t\t\t\t\t<BubbleContent>Hold it. The billing migration has to go out in the same release.</BubbleContent>\n\t\t\t\t\t</Bubble>\n\t\t\t\t</MessageContent>\n\t\t\t</Message>\n\n\t\t\t<Message>\n\t\t\t\t<MessageContent>\n\t\t\t\t\t<Bubble variant="muted">\n\t\t\t\t\t\t<BubbleContent>Understood. The migration lands after the 2pm review.</BubbleContent>\n\t\t\t\t\t</Bubble>\n\t\t\t\t</MessageContent>\n\t\t\t</Message>\n\n\t\t\t<Message align="end">\n\t\t\t\t<MessageContent>\n\t\t\t\t\t<Bubble>\n\t\t\t\t\t\t<BubbleContent>Then I will cut the tag straight after.</BubbleContent>\n\t\t\t\t\t</Bubble>\n\t\t\t\t</MessageContent>\n\t\t\t</Message>\n\t\t</div>\n\t);\n}\n',
